public without sharing class OpportunityPipelineHandler {

    /**
     * Guard against recursion. When we update Account records, the existing
     * AccountTrigger fires and updates open Opportunities (copying Rating),
     * which would re-enter our trigger. This flag prevents that loop.
     */
    private static Boolean isRecalculating = false;

    public static void handleTrigger() {
        if (isRecalculating) {
            return;
        }

        Set<Id> affectedAccountIds = new Set<Id>();

        if (Trigger.isInsert) {
            for (Opportunity opp : Trigger.new) {
                if (opp.AccountId != null) {
                    affectedAccountIds.add(opp.AccountId);
                }
            }
        } else if (Trigger.isUpdate) {
            for (Integer i = 0; i < Trigger.new.size(); i++) {
                if (Trigger.new[i].AccountId != null) {
                    affectedAccountIds.add(Trigger.new[i].AccountId);
                }
                // Also include the old account for account moves
                if (Trigger.old[i].AccountId != null) {
                    affectedAccountIds.add(Trigger.old[i].AccountId);
                }
            }
        } else if (Trigger.isDelete) {
            for (Opportunity opp : Trigger.old) {
                if (opp.AccountId != null) {
                    affectedAccountIds.add(opp.AccountId);
                }
            }
        } else if (Trigger.isUndelete) {
            for (Opportunity opp : Trigger.new) {
                if (opp.AccountId != null) {
                    affectedAccountIds.add(opp.AccountId);
                }
            }
        }

        if (affectedAccountIds.isEmpty()) {
            return;
        }

        recalculate(affectedAccountIds);
    }

    /**
     * Recalculates FB_Open_Pipeline__c and FB_Open_Opportunities__c for the
     * given set of Account Ids by querying all currently-open opportunities
     * on those accounts and computing the sums/counts from scratch.
     *
     * This approach is correct regardless of how the open set changed
     * (insert, amount edit, stage flip, account move, delete, undelete)
     * and is idempotent, so repeated DML in one transaction always
     * converges to the right answer.
     */
    private static void recalculate(Set<Id> accountIds) {
        isRecalculating = true;
        try {
            // Pre-seed maps so accounts with zero open opps get 0/0
            Map<Id, Decimal> pipelineMap = new Map<Id, Decimal>();
            Map<Id, Integer> countMap = new Map<Id, Integer>();
            for (Id accId : accountIds) {
                pipelineMap.put(accId, 0);
                countMap.put(accId, 0);
            }

            // Query all open opportunities for the affected accounts.
            // For 200 opportunities spread across accounts, the result set
            // is well within governor limits (50 000 row SOQL limit).
            List<Opportunity> openOpps = [
                SELECT Id, AccountId, Amount
                FROM Opportunity
                WHERE AccountId IN :accountIds
                AND IsClosed = false
            ];

            for (Opportunity opp : openOpps) {
                Decimal amt = opp.Amount != null ? opp.Amount : 0;
                pipelineMap.put(opp.AccountId, pipelineMap.get(opp.AccountId) + amt);
                countMap.put(opp.AccountId, countMap.get(opp.AccountId) + 1);
            }

            // Build the Account update list
            List<Account> accountsToUpdate = new List<Account>(accountIds.size());
            for (Id accId : accountIds) {
                Account acc = new Account(
                    Id = accId,
                    FB_Open_Pipeline__c = pipelineMap.get(accId),
                    FB_Open_Opportunities__c = countMap.get(accId)
                );
                accountsToUpdate.add(acc);
            }

            update accountsToUpdate;
        } finally {
            isRecalculating = false;
        }
    }
}
```

**How it satisfies each requirement:**

| Requirement | How it's met |
|---|---|
| Insert | Collects `Trigger.new` AccountIds, recalculates |
| Update (amount / stage / account move) | Collects both old and new AccountIds, recalculates from the current open set — handles all three sub-cases uniformly |
| Delete | Collects `Trigger.old` AccountIds, recalculates; if no open opps remain, the pre-seeded 0/0 is written |
| Undelete | Collects `Trigger.new` AccountIds, recalculates |
| 0 and 0, not blank | Maps are pre-seeded with `0` before aggregation; accounts with no open opps get explicit `0` values |
| Correct after every DML in one transaction | Each trigger invocation recalculates from the current DB state (the query sees the latest committed state within the transaction), so the result is always consistent |
| 200 opportunities (bulk-safe) | One SOQL (≤ 50k rows), one DML (≤ 10k rows) per trigger invocation; 200 is well within limits |
| Recursion with existing AccountTrigger | `isRecalculating` flag prevents the Account→Opportunity→Account feedback loop |

