    protected override Object createService(Type serviceType) {
        if (serviceType == IAccountsService.class) {
            return new AccountsServiceImpl();
        }
        return null;
    }

    // ─── Selector ────────────────────────────────────────────────────────

    protected override fflib_ISObjectSelector createSelector(Schema.SObjectType sObjectType) {
        if (sObjectType == Account.SObjectType) {
            return new AccountsSelector();
        }
        if (sObjectType == Contact.SObjectType) {
            return new ContactsSelector();
        }
        return null;
    }

    // ─── Domain ──────────────────────────────────────────────────────────

    protected override fflib_ISObjectDomain createDomain(Schema.SObjectType sObjectType) {
        if (sObjectType == Account.SObjectType) {
            return new Accounts(new List<Account>());
        }
        return null;
    }

    protected override fflib_ISObjectDomain createDomain(Set<Id> ids) {
        if (ids == null || ids.isEmpty()) {
            return new Accounts(new List<Account>());
        }
        fflib_ISObjectSelector selector = Selector.newInstance(Account.SObjectType);
        List<SObject> records = selector.selectSObjectsById(ids);
        return new Accounts((List<Account>) records);
    }

    protected override fflib_ISObjectDomain createDomain(List<SObject> records) {
        if (records == null || records.isEmpty()) {
            return new Accounts(new List<Account>());
        }
        if (records[0] instanceof Account) {
            return new Accounts((List<Account>) records);
        }
        return null;
    }

