        for (Opportunity o : (List<Opportunity>) getUpdatedRecords()) {
            validateAmountNotNegative(o);
            validateWonAmountNotChanged(o);
        }
    }

    private void validateAmountNotNegative(Opportunity o) {
        if (o.Amount != null && o.Amount < 0) {
            error('Amount cannot be negative.', o, Opportunity.Amount);
        }
    }

    private void validateWonAmountNotChanged(Opportunity o) {
        Opportunity oldOpp = (Opportunity) getOldRecords().get(o.Id);
        if (oldOpp.StageName == 'Closed Won' && o.Amount != oldOpp.Amount) {
            error('Amount cannot change on a won opportunity.', o, Opportunity.Amount);
        }
    }
}
