```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_MS = 300;
const MIN_CHARS = 2;

export default class ContactSearch extends LightningElement {
    searchTerm = '';
    results = [];
    errorMessage = null;

    _debounceTimer = null;
    _requestToken = 0;

    handleSearchChange(event) {
        this.searchTerm = event.target.value;
        const trimmed = this.searchTerm.trim();

        // Clear any pending debounced call
        if (this._debounceTimer !== null) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = null;
        }

        // Fewer than 2 characters: cancel, clear results
        if (trimmed.length < MIN_CHARS) {
            this._requestToken++; // invalidate any in-flight response
            this.results = [];
            this.errorMessage = null;
            return;
        }

        // Debounce: schedule the search 300 ms after the last keystroke
        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = null;
            this._executeSearch(trimmed);
        }, DEBOUNCE_MS);
    }

    _executeSearch(searchTerm) {
        const token = ++this._requestToken;
        this.errorMessage = null;

        searchContacts({ searchTerm })
            .then((contacts) => {
                // Only apply the response if it is the most recent request
                if (token !== this._requestToken) {
                    return;
                }
                this.results = contacts;
            })
            .catch((error) => {
                if (token !== this._requestToken) {
                    return;
                }
                this.results = [];
                this.errorMessage = error.body ? error.body.message : String(error);
            });
    }

    disconnectedCallback() {
        // Prevent a pending debounced call from firing after removal
        if (this._debounceTimer !== null) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = null;
        }
        // Invalidate any in-flight Apex response so it won't mutate state
        this._requestToken++;
    }
}
