public class EmployerService {

    /**
     * Sets the current employer (Organization Account) for a set of Contacts
     * using the NPSP Affiliation model.
     *
     * For each contact in the map:
     *   - A Current, primary NPSP_Affiliation__c is ensured to the target Organization.
     *   - Any previous primary affiliation is demoted to Former (EndDate__c = today,
     *     IsPrimary__c = false) by NPSP's standard automation when a new primary is set.
     *   - The Contact's Household Account (AccountId) is never touched.
     *   - If the target Organization is already the contact's current primary, no change is made.
     *
     * Governor-limit profile (per call, up to 200 contacts):
     *   1 SOQL  (existing affiliations for the batch)
     *   2 DMLs  (update existing, insert new)
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Build the set of contact IDs that have a non-null employer
        Set<Id> contactIds = new Set<Id>();
        for (Id contactId : employerByContactId.keySet()) {
            if (employerByContactId.get(contactId) != null) {
                contactIds.add(contactId);
            }
        }
        if (contactIds.isEmpty()) {
            return;
        }

        // ── SOQL 1 ──────────────────────────────────────────────────────────
        // Fetch every existing affiliation for the target contacts so we can
        // determine what already exists and what needs to change.
        List<NPSP_Affiliation__c> existingAffs = [
            SELECT Id,
                   Contact__c,
                   Account__c,
                   IsPrimary__c,
                   StartDate__c,
                   EndDate__c
            FROM NPSP_Affiliation__c
            WHERE Contact__c IN :contactIds
        ];

        // ── Index: contactId → orgId → List<Affiliation> ───────────────────
        Map<Id, Map<Id, List<NPSP_Affiliation__c>>> affByContactAndOrg =
            new Map<Id, Map<Id, List<NPSP_Affiliation__c>>>();

        for (NPSP_Affiliation__c aff : existingAffs) {
            if (!affByContactAndOrg.containsKey(aff.Contact__c)) {
                affByContactAndOrg.put(aff.Contact__c,
                    new Map<Id, List<NPSP_Affiliation__c>>());
            }
            Map<Id, List<NPSP_Affiliation__c>> orgBucket =
                affByContactAndOrg.get(aff.Contact__c);
            if (!orgBucket.containsKey(aff.Account__c)) {
                orgBucket.put(aff.Account__c, new List<NPSP_Affiliation__c>());
            }
            orgBucket.get(aff.Account__c).add(aff);
        }

        // ── Determine the DML payloads ──────────────────────────────────────
        Date today = Date.today();
        List<NPSP_Affiliation__c> toUpdate = new List<NPSP_Affiliation__c>();
        List<NPSP_Affiliation__c> toInsert = new List<NPSP_Affiliation__c>();

        for (Id contactId : contactIds) {
            Id orgId = employerByContactId.get(contactId);

            Map<Id, List<NPSP_Affiliation__c>> orgBucket =
                affByContactAndOrg.get(contactId);

            if (orgBucket != null) {
                List<NPSP_Affiliation__c> targetAffs = orgBucket.get(orgId);

                if (targetAffs != null) {
                    // Does a Current + Primary affiliation to this org already exist?
                    Boolean alreadyCurrentPrimary = false;
                    for (NPSP_Affiliation__c aff : targetAffs) {
                        if (aff.IsPrimary__c && aff.EndDate__c == null) {
                            alreadyCurrentPrimary = true;
                            break;
                        }
                    }
                    if (alreadyCurrentPrimary) {
                        // Requirement: "nothing changes" – skip
                        continue;
                    }

                    // Promote the existing (possibly Former) affiliation to
                    // Current + Primary.  NPSP's trigger/flow will detect the
                    // new primary and automatically demote the old one.
                    NPSP_Affiliation__c aff = targetAffs[0];
                    aff.IsPrimary__c = true;
                    aff.EndDate__c   = null;       // make it Current
                    if (aff.StartDate__c == null) {
                        aff.StartDate__c = today;
                    }
                    toUpdate.add(aff);
                } else {
                    // No existing row for this org → create one
                    toInsert.add(new NPSP_Affiliation__c(
                        Contact__c   = contactId,
                        Account__c   = orgId,
                        IsPrimary__c = true,
                        StartDate__c = today
                    ));
                }
            } else {
                // Contact has no affiliations at all → create one
                toInsert.add(new NPSP_Affiliation__c(
                    Contact__c   = contactId,
                    Account__c   = orgId,
                    IsPrimary__c = true,
                    StartDate__c = today
                ));
            }
        }

        // ── DML 1: promote existing rows ────────────────────────────────────
        if (!toUpdate.isEmpty()) {
            UPDATE toUpdate;
        }

        // ── DML 2: create new rows ──────────────────────────────────────────
        if (!toInsert.isEmpty()) {
            INSERT toInsert;
        }
        // NPSP's standard affiliation trigger/flow fires on the above DML and
        // handles demoting any previous primary (EndDate__c → today,
        // IsPrimary__c → false) and maintaining any derived Contact fields.
    }
}
