public class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;
        public Date startDate;
        public Integer installments;
        public String paymentMethod;
    }

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // Validate all requests before any DML
        for (GiftRequest req : requests) {
            if (req == null) {
                throw new RecurringGiftException('Gift request cannot be null.');
            }
            if (req.contactId == null) {
                throw new RecurringGiftException('Contact Id is required.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException('Amount must be a positive value.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException('Day of month must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException('Start date is required.');
            }
        }

        // Build Enhanced Recurring Donation records
        List<npe03__Recurring_Donation__c> nrdList = new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {
            npe03__Recurring_Donation__c nrd = new npe03__Recurring_Donation__c();

            // Donor and amount
            nrd.npe03__Contact__c = req.contactId;
            nrd.npe03__Amount__c = req.amount;

            // Schedule: every month on the specified day
            nrd.npe03__Frequency__c = 'Monthly';
            nrd.npe03__Interval__c = 1;
            nrd.npe03__Start_Date__c = req.startDate;
            nrd.npe03__Status__c = 'Active';
            nrd.npe03__Installment_Frequency_Type__c = 'Days';

            // Day of month: 31 means last day of month
            if (req.dayOfMonth == 31) {
                nrd.npe03__LastDay__c = true;
            } else {
                nrd.npe03__LastDay__c = false;
                nrd.npe03__Installment_Frequency_Days__c = req.dayOfMonth;
            }

            // Payment method
            if (String.isNotBlank(req.paymentMethod)) {
                nrd.npe03__Payment_Type__c = req.paymentMethod;
            }

            // End condition: null or 0 = open-ended
            if (req.installments != null && req.installments > 0) {
                nrd.npe03__End_Count__c = req.installments;
                nrd.npe03__End_Type__c = 'Count';
            }

            nrdList.add(nrd);
        }

        // Single DML statement – NPSP will generate installment opportunities
        insert nrdList;

        // Return new Ids in request order
        List<Id> ids = new List<Id>();
        for (npe03__Recurring_Donation__c nrd : nrdList) {
            ids.add(nrd.Id);
        }

        return ids;
    }
}
```

**Key design decisions:**

| Concern | Resolution |
|---------|-----------|
| **Bulk safety** | One `insert` DML for all 200 records; zero SOQL queries (all data comes from the input). |
| **Validation before DML** | The entire validation loop runs before the `insert`, so no partial writes occur on a bad batch. |
| **Day 31 → Last Day** | `npe03__LastDay__c = true` is NPSP's built-in mechanism; days 29/30 are stored literally in `npe03__Installment_Frequency_Days__c`. |
| **Open-ended vs fixed** | `installments` null or 0 leaves both `End_Date__c` and `End_Count__c` null (open-ended). A positive value sets `End_Count__c` and `End_Type__c = 'Count'`. |
| **NPSP generates Opportunities** | We only create the `npe03__Recurring_Donation__c` record with `Status = 'Active'`; NPSP's own scheduled processes/batches handle installment opportunity creation. |
| **Order preservation** | The `insert` list preserves order, and we read back `nrd.Id` in the same iteration order. |

