public class HouseholdService {

    /**
     * Creates a single NPSP Household Account for the given contacts.
     * The first contact in the list becomes the household's primary contact.
     * NPSP handles household naming automatically; we never set Account.Name.
     *
     * @param members  New Contact records (no Id, no AccountId) to place in one household.
     * @return         The Id of the newly created Household Account.
     * @throws IllegalArgumentException if members is null or empty.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty.');
        }

        // Resolve the Individual record type dynamically (no hard-coded IDs)
        Id individualRTId = getRecordTypeId('Contact', 'Individual');

        // Stamp every contact with the Individual RT and clear any stale AccountId
        for (Contact c : members) {
            c.RecordTypeId = individualRTId;
            c.AccountId = null;
        }

        // --- Step 1: insert the first (primary) contact on its own ---
        // NPSP's trigger framework detects a new Individual contact with no AccountId,
        // creates a Household account, links the contact, and names the household.
        Contact primary = members.get(0);
        insert primary;

        Id householdId = primary.AccountId;

        // Defensive fallback: if the NPSP trigger did not fire (e.g. partial install),
        // create the household explicitly so the call still succeeds.
        if (householdId == null) {
            Id householdRTId = getRecordTypeId('Account', 'Household');
            Account household = new Account(RecordTypeId = householdRTId);
            insert household;
            householdId = household.Id;
            primary.AccountId = householdId;
            update primary; // NPSP naming trigger will fire here
        }

        // --- Step 2: link and insert the remaining contacts to the same household ---
        if (members.size() > 1) {
            List<Contact> remaining = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                members.get(i).AccountId = householdId;
                remaining.add(members.get(i));
            }
            insert remaining;
            // NPSP naming trigger re-evaluates the household name to include all members
        }

        return householdId;
    }

    /**
     * Looks up a RecordType by object and developer name without hard-coding the 15/18-char Id.
     */
    private static Id getRecordTypeId(String sobjectType, String developerName) {
        RecordType rt = [
            SELECT Id
            FROM RecordType
            WHERE SobjectType = :sobjectType
              AND DeveloperName = :developerName
            LIMIT 1
        ];
        return rt.Id;
    }
}
```

**How it satisfies each requirement:**

| Requirement | How |
|---|---|
| Real NPSP household (correct Record Type) | Resolved via `getRecordTypeId('Account','Household')`; contacts get `'Contact','Individual'`. NPSP's own triggers create the account with that RT. |
| NPSP names the account / generates greetings | We never set `Account.Name`; NPSP's after-insert trigger on Contact handles it. |
| First contact = primary contact | It is inserted first, triggering household creation, so NPSP's naming logic treats it as the primary. |
| No orphan / extra households | Only one household is ever created (by the NPSP trigger on the first contact, or the defensive fallback). All subsequent contacts are linked to that same `AccountId` before their insert. |
| No hard-coded Record Type IDs | Looked up by `DeveloperName` + `SobjectType` at runtime. |
| `IllegalArgumentException` on null/empty | First statement in the method. |

