public with sharing class EmployeeDirectoryService {

    public static List<FB_Employee__c> getDirectory() {
        // If the running user cannot read the object at all, return an empty list
        if (!Schema.sObjectType.FB_Employee__c.getDescribe().isReadable()) {
            return new List<FB_Employee__c>();
        }

        // Build the field list, including only custom fields the user can read
        List<String> fields = new List<String>{ 'Id', 'Name' };

        if (Schema.sObjectType.FB_Employee__c.getFields().get('Department__c').getDescribe().isReadable()) {
            fields.add('Department__c');
        }
        if (Schema.sObjectType.FB_Employee__c.getFields().get('Salary__c').getDescribe().isReadable()) {
            fields.add('Salary__c');
        }
        if (Schema.sObjectType.FB_Employee__c.getFields().get('Personal_Email__c').getDescribe().isReadable()) {
            fields.add('Personal_Email__c');
        }

        // Dynamic SOQL respects the class-level 'with sharing', so only records
        // the user has access to via sharing rules are returned.
        String soql = 'SELECT ' + String.join(fields, ', ')
            + ' FROM FB_Employee__c ORDER BY Name ASC';

        return (List<FB_Employee__c>) Database.query(soql);
    }
}
