public class ContactImportService {

    public static void importContacts(List<Contact> contacts) {
        // Bypass the welcome task action for each contact being imported.
        // The bypass is scoped to these specific SObject instances, so any
        // Contact inserted later in the same transaction will still fire
        // TA_Contact_CreateWelcomeTask as usual.
        for (Contact c : contacts) {
