global class TA_Contact_PreventDuplicateEmail implements Trigger_Action {
    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    global void run() {
        if (Trigger.isInsert) {
            handleBeforeInsert();
        }
        else if (Trigger.isUpdate) {
            handleBeforeUpdate();
        }
    }

    private void handleBeforeInsert() {
        Set<Id> accountIds = new Set<Id>();

        for (Contact c : Trigger.new) {
            if (c.AccountId != null && String.isNotBlank(c.Email)) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<String, Set<Id>> existingMap = buildExistingMap(accountIds);
        Map<String, Id> batchAccepted = new Map<String, Id>();

        for (Contact c : Trigger.new) {
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }

            String key = c.AccountId + '|' + c.Email.toLowerCase();

            if (hasConflict(existingMap, batchAccepted, key, null)) {
                c.addError(ERROR_MESSAGE);
            }
            else {
                batchAccepted.put(key, c.Id);
            }
        }
    }

    private void handleBeforeUpdate() {
        Set<Id> accountIds = new Set<Id>();

        for (Integer i = 0; i < Trigger.new.size(); i++) {
            Contact newC = Trigger.new[i];
            Contact oldC = Trigger.old[i];

            if (isRelevantChange(oldC, newC) && newC.AccountId != null && String.isNotBlank(newC.Email)) {
                accountIds.add(newC.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<String, Set<Id>> existingMap = buildExistingMap(accountIds);
        Map<String, Id> batchAccepted = new Map<String, Id>();

        for (Integer i = 0; i < Trigger.new.size(); i++) {
            Contact newC = Trigger.new[i];
            Contact oldC = Trigger.old[i];

            if (!isRelevantChange(oldC, newC)) {
                continue;
            }
            if (newC.AccountId == null || String.isBlank(newC.Email)) {
                continue;
            }

            String key = newC.AccountId + '|' + newC.Email.toLowerCase();

            if (hasConflict(existingMap, batchAccepted, key, newC.Id)) {
                newC.addError(ERROR_MESSAGE);
            }
            else {
                batchAccepted.put(key, newC.Id);
            }
        }
    }

    private Boolean isRelevantChange(Contact oldC, Contact newC) {
        return oldC.Email != newC.Email || oldC.AccountId != newC.AccountId;
    }

    private Map<String, Set<Id>> buildExistingMap(Set<Id> accountIds) {
        Map<String, Set<Id>> result = new Map<String, Set<Id>>();
        for (Contact c : [SELECT Id, AccountId, Email FROM Contact WHERE AccountId IN :accountIds]) {
            if (String.isNotBlank(c.Email)) {
                String key = c.AccountId + '|' + c.Email.toLowerCase();
                if (!result.containsKey(key)) {
                    result.put(key, new Set<Id>());
                }
                result.get(key).add(c.Id);
            }
        }
        return result;
    }

    private Boolean hasConflict(Map<String, Set<Id>> existingMap, Map<String, Id> batchAccepted, String key, Id selfId) {
        if (existingMap.containsKey(key)) {
            for (Id id : existingMap.get(key)) {
                if (id != selfId) {
                    return true;
                }
            }
        }
        if (batchAccepted.containsKey(key) && batchAccepted.get(key) != selfId) {
            return true;
        }
        return false;
    }
}
