public class TA_Lead_NormalizeContactInfo implements TriggerAction {
    private Lead lead;

    public TA_Lead_NormalizeContactInfo(SObject record) {
        this.lead = (Lead) record;
    }

    public void execute() {
        // Email: trim and lowercase; null stays null
        if (lead.Email != null) {
            lead.Email = lead.Email.trim().toLowerCase();
        }

        // Company: trim; null stays null
        if (lead.Company != null) {
            lead.Company = lead.Company.trim();
        }

        // LeadSource: set to 'Web' when blank (null or whitespace-only)
        if (String.isBlank(lead.LeadSource)) {
            lead.LeadSource = 'Web';
        }
    }
}
