public class TA_Contact_Queries {
    private static TA_Contact_Queries instance;

    public Map<Id, Account> accountsById = new Map<Id, Account>();

    private TA_Contact_Queries() {}

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    public class Service implements Trigger_Action {
        public void execute(Trigger_Action__mdt actionRecord, Object[] records) {
            List<Contact> contacts = (List<Contact>) records;

            Set<Id> accountIds = new Set<Id>();
            for (Contact c : contacts) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }

            Map<Id, Account> newMap = new Map<Id, Account>();
            if (!accountIds.isEmpty()) {
                newMap = [SELECT Id, BillingStreet, BillingCity, BillingPostalCode,
                           BillingCountry, AccountSource
                          FROM Account
                          WHERE Id IN :accountIds];
            }

            TA_Contact_Queries.getInstance().accountsById = newMap;
        }
    }
}
